Caching para Ollama com Redis:

```python
import redis
import hashlib
import json
from functools import wraps

redis_client = redis.Redis(host='localhost', port=6379, db=0)

def cache_ollama_response(expiry=3600):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Crie chave única do prompt
            prompt = kwargs.get('prompt', args[0] if args else '')
            model = kwargs.get('model', 'llama3')
            cache_key = f"ollama:{model}:{hashlib.sha256(prompt.encode()).hexdigest()}"

            # Tente cache
            cached = redis_client.get(cache_key)
            if cached:
                return json.loads(cached)

            # Execute e salve
            result = func(*args, **kwargs)
            redis_client.setex(
                cache_key,
                expiry,
                json.dumps(result)
            )
            return result
        return wrapper
    return decorator

# Uso
@cache_ollama_response(expiry=1800)  # 30 min
def generate_with_ollama(prompt, model='llama3'):
    response = requests.post(
        'http://localhost:11434/api/generate',
        json={'model': model, 'prompt': prompt, 'stream': False}
    )
    return response.json()

# Cache semântico (similaridade)
def semantic_cache(prompt, threshold=0.95):
    embedding = get_embedding(prompt)  # Use modelo de embeddings
    similar = redis_client.ft().search(
        f"@embedding:[{embedding} {threshold}]"
    )
