#!/usr/bin/env python3
import click
import requests
import json
import subprocess

OLLAMA_URL = "http://localhost:11434"

@click.group()
def cli():
    "CLI para gerenciar Ollama"
    pass

@cli.command()
@click.argument('model')
@click.option('--prompt', '-p', required=True)
@click.option('--stream/--no-stream', default=False)
def generate(model, prompt, stream):
    "Gera texto com um modelo"
    response = requests.post(
        f"{OLLAMA_URL}/api/generate",
        json={'model': model, 'prompt': prompt, 'stream': stream},
        stream=stream
    )

    if stream:
        for line in response.iter_lines():
            if line:
                chunk = json.loads(line)
                print(chunk.get('response', ''), end='', flush=True)
    else:
        print(response.json()['response'])

@cli.command()
def list():
    "Lista modelos disponíveis"
    r = requests.get(f"{OLLAMA_URL}/api/tags")
    models = r.json()['models']
    for m in models:
        print(f"{m['name']}: {m['size']}")

@cli.command()
@click.argument('model')
def pull(model):
    "Baixa um modelo"
    subprocess.run(['ollama', 'pull', model])

@cli.command()
@click.argument('model')
@click.confirmation_option(prompt='Tem certeza?')
def rm(model):
    "Remove um modelo"
    subprocess.run(['ollama', 'rm', model])

@cli.command()
@click.argument('model')
def ps(model):
    "Mostra status do modelo"
    r = requests.get(f"{OLLAMA_URL}/api/ps")
    models = r.json().get('models', [])
    for m in models:
        if m['name'] == model:
            print(f"Modelo: {m['name']}")
            print(f"Tamanho: {m['size']}")
            print(f"Processador: {m.get('details', {}).get('processor', 'N/A')}")

if __name__ == '__main__':
    cli()
