   from flask import Flask, request, Response
   import ldap3

   app = Flask(__name__)

   @app.route('/verify')
   def verify():
       auth = request.authorization
       if not auth:
           return Response('Unauthorized', 401,
               {'WWW-Authenticate': 'Basic realm="Ollama"'})

       # Conecte ao LDAP
       server = ldap3.Server('ldap.company.com')
       conn = ldap3.Connection(
           server,
           user=f"{auth.username}@company.com",
           password=auth.password
       )

       if conn.bind():
           # Verifique grupo autorizado
           conn.search(
               'ou=groups,dc=company,dc=com',
               f'(&(cn=ollama-users)(member={auth.username}))'
           )
           if conn.entries:
               return Response('OK', 200)
       return Response('Unauthorized', 401)
