Model Registry para Ollama:

```python
from dataclasses import dataclass
from datetime import datetime
from typing import List, Optional
import json
import hashlib

@dataclass
class ModelVersion:
    name: str
    version: str
    gguf_path: str
    modelfile: str
    tags: List[str]
    metrics: dict
    created_at: datetime
    checksum: str
    stage: str = "development"  # development, staging, production, archived

class ModelRegistry:
    def __init__(self, db_path="/var/lib/ollama-registry"):
        self.db_path = db_path
        self.models = self._load()

    def register(self, version: ModelVersion):
        # Valida checksum
        with open(version.gguf_path, 'rb') as f:
            actual_checksum = hashlib.sha256(f.read()).hexdigest()
        if actual_checksum != version.checksum:
            raise ValueError("Checksum mismatch!")

        # Registra
        self.models[f"{version.name}:{version.version}"] = version
        self._save()

    def promote(self, name: str, version: str, to_stage: str):
        key = f"{name}:{version}"
        if key not in self.models:
            raise KeyError(f"Model {key} not found")

        # Valida promoção
        valid_flows = {
            "development": ["staging"],
            "staging": ["production", "development"],
            "production": ["archived"]
        }

        current = self.models[key].stage
        if to_stage not in valid_flows.get(current, []):
            raise ValueError(f"Cannot promote {current} -> {to_stage}")

        self.models[key].stage = to_stage
        self._save()

    def get_production_model(self, name: str) -> Optional[ModelVersion]:
        versions = [v for v in self.models.values()
                   if v.name == name and v.stage == "production"]
        return max(versions, key=lambda v: v.created_at) if versions else None

    def list_by_stage(self, stage: str) -> List[ModelVersion]:
        return [v for v in self.models.values() if v.stage == stage]

    def _load(self):
        try:
             with open(f"{self.db_path}/registry.json") as f:
                return {k: ModelVersion(**v) for k, v in json.load(f).items()}
        except FileNotFoundError:
            return {}

    def _save(self):
        with open(f"{self.db_path}/registry.json", 'w') as f:
            json.dump({k: v.__dict__ for k, v in self.models.items()}, f, default=str)
